/* JTC Summit, OSM way 33738028. Original geometry in metres.
 * Curved curtain wall, stepped cream office wings, four-level public podium
 * and a recessed curved louvre crown. No logos or photographic textures.
 */
{
const {register,scale,out}=SGJE;
// Own measured registration height; shared catalogue is regenerated by the lead.
SGJE.data.jtc_summit.height=150.7;
SGJE.data.jtc_summit.height_source='Measured roof-minus-ground (image-only reference metadata)';
register('jtc_summit','裕廊集团大厦','JTC Summit',77,(b,D)=>{
 const P=D.parts[0].p;
 // OSM building-part ways 368005257 (curved curtain wall) and 463193388
 // (cream rear office bar), fetched from the OSM API 2026-11-01. Both lie
 // within parent way 33738028; metres east/south at the supplied anchor.
 const C=[[-36.81,-1.08],[-42.88,-5.06],[-41.49,8.48],[-36.81,18.71],[-28.83,26],[-19.98,30.16],[-10.9,33.09],[-1.76,33.11],[6.91,31.72],[2.4,28.95]];
 const W=[[-36.81,-1.08],[2.4,28.95],[13.33,14.02],[-25.01,-15.81]];
 const pt=(u,v)=>[.830*u+.558*v,.558*u-.830*v];
 b.prism(P,-1,22.6,'#a7aaa1');b.facade(out(P,.06),1,22.1,4,3.2,'#577a7e','#c5d0c7',.22);
 // The public podium is a finely ribbed round volume, distinct from the
 // taller cream wings. Horizontal external shades follow its OSM curve.
 for(let y=2.4;y<22.3;y+=1.35)b.band(out(P,.16),y,.20,'#c2cbc3');
 b.cap(P,22.6,'#969f96');b.rim(P,22.95,'#d2d6ca',.38);
 b.prism(W,22.4,132.4,'#b4b5a7');
 b.facade(out(W,.06),22.7,132.2,4.25,2.7,'#557476','#cccabd',0);
 for(let y=22.7;y<132.4;y+=4.25){b.band(out(W,.10),y,1.58,'#c7c6b9');b.band(out(W,.65),y+1.52,.18,'#afb6af');}
 // On the northeast rear face, cream piers interrupt the central ribbon
 // into punched windows, matching the north/east image references.
 const back=[W[3],W[2]],dx=back[1][0]-back[0][0],dz=back[1][1]-back[0][1],L=Math.hypot(dx,dz);
 for(let j=4;j<15;j++){const t=j/19,x=back[0][0]+dx*t,z=back[0][1]+dz*t;b.beam([x+.12,22.6,z-.16],[x+.12,132.3,z-.16],.72,'#c7c6b9');}
 b.roof(W,132.5,2);
 b.prism(C,0,139.1,'#55797b',2);b.facade(out(C,.06),1.1,138.9,4.25,2.7,'#547d80','#9baeb0',0);
 // Three narrow metallic rails bracket the floor spandrel, the characteristic
 // continuous striped rhythm seen in the Commons daytime/dusk photographs.
 const front=out(C,.18).slice(0,9);
 for(let y=3.1;y<139;y+=4.25)for(const dy of [0,.34,.70])for(let i=0;i<front.length-1;i++){
  const a=front[i],q=front[i+1];b.beam([a[0],y+dy,a[1]],[q[0],y+dy,q[1]],dy===0?.20:.12,'#cbd2c8');
 }
 for(const a of [C[0],C[9]])b.box(a[0],0,a[1],.75,139.3,.75,'#d9ded4');
 // Tall recessed service slit in the centre of the cream rear elevation.
 const spine=[[-10.1,-4.2],[-6.5,-1.4],[-7.1,-.6],[-10.7,-3.4]];
 b.prism(spine,22.7,138,'#354f52');
 for(let y=23;y<138;y+=.95)b.band(out(spine,.08),y,.13,'#798e89');
 const crown=scale(C,.88);b.prism(crown,139.1,147.6,'#526d6c');
 for(let y=139.3;y<147.8;y+=.80)b.band(out(crown,.20),y,.19,'#9aa9a1');
 b.rim(crown,147.8,'#bec8bb',.38);b.cap(crown,147.6,'#7c8981');
 const mast=[-31,4];b.box(mast[0],147.8,mast[1],.2,2.9,.2,'#aeb8b0');
 // Open safety railing above the lower rear bar.
 const rear=scale(W,.94);
 rear.forEach((a,i)=>{const q=rear[(i+1)%rear.length];for(const y of [133.7,135,136.3])b.beam([a[0],y,a[1]],[q[0],y,q[1]],.18,'#9faeaa');});
 // The public podium has a central glazed atrium and segmented roof shades.
 const atrium=[[-6,-36],[27,-14],[13,7],[-20,-16]];
 b.prism(atrium,22.6,23.3,'#6f8886',2);b.rim(atrium,23.5,'#d2d8cb',.48);
 for(let t=0;t<=1;t+=.09){const a=atrium[0],q=atrium[1],c=atrium[3],d=atrium[2];b.beam([a[0]+(q[0]-a[0])*t,23.55,a[1]+(q[1]-a[1])*t],[c[0]+(d[0]-c[0])*t,23.55,c[1]+(d[1]-c[1])*t],.20,'#c4d0ca');}
 // Entrance glazing, low projecting shelter and slender supports stay at the
 // true podium perimeter rather than enlarging the district silhouette.
 const ent=pt(33,-31);b.box(ent[0],5.5,ent[1],13,.35,4,'#c3cec7',-.592);
 for(const u of [28,38]){const a=pt(u,-31);b.box(a[0],0,a[1],.35,5.5,.35,'#b8c5bf');}
 // Material-only, module-local dusk occupancy correction. Batch.flush creates
 // the inherited PBR/lmMat materials after this build callback, so wrap that
 // one flush and clone only this group's glass material. Shared materials and
 // every daytime shading/geometry path remain untouched.
 const inheritedFlush=b.flush;
 b.flush=function(group){
  const result=inheritedFlush.call(this,group);
  for(const mesh of group.children){
   if(!mesh.isMesh||mesh.material.customProgramCacheKey()!=='sgbv-pbr-v1-2')continue;
   const inherited=mesh.material,local=inherited.clone(),compile=inherited.onBeforeCompile;
   local.onBeforeCompile=function(shader,renderer){
    compile.call(this,shader,renderer);
    shader.fragmentShader=shader.fragmentShader
     .replace(/step\(r, 0\.58( \* uOcc)?\)/g,(_,occ)=>'step(r, mix(0.28, 0.055, step(uBase + 25.0, vWP.y))'+(occ||'')+')')
     .replace('step(0.28, fract(vWP.y / uFH))','step(0.78, fract(vWP.y / uFH)) * (1.0 - step(0.94, fract(vWP.y / uFH)))')
     .replace(/vec3 wc = mix\(vec3\(1\.0, 0\.8, 0\.56\), vec3\(0\.78, 0\.87, 1\.0\), step\(0\.55, fract\(r \* 7\.13\)\)\);/,'vec3 wc = vec3(1.0, 0.86, 0.65);')
     .replace(' + LC * LK * smoothstep(0.93, 1.0, hN) * (0.9 + 0.8 * uShow)','')
     .replace(' + uLC * uLK * smoothstep(0.93, 1.0, hN) * 0.9','');
   };
   local.customProgramCacheKey=()=> 'sgbv-pbr-v1-2-jtc-dusk-sparse-v1';
   local.needsUpdate=true;mesh.material=local;
  }
  return result;
 };

});
}
